package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.web.ObjectResponse;

/**
 * {@code GET /api/invoices/all} — every invoice across ALL projects, each carrying the NAME of the
 * project it bills and its lifecycle status, so one page can list them all in one place (the
 * per-project {@link InvoicesGetLogic} only lists a single project's). Ordered by id for a stable
 * list. Wired by {@code officefloor/rest/api/invoices/all.GET.yml}.
 */
public class AllInvoicesGetLogic {

    public void service(InvoiceRepository invoices, ProjectRepository projects,
            PaymentRepository payments, ObjectResponse<List<InvoiceView>> response) {
        Map<Long, String> nameByProject = projects.findAll().stream()
                .collect(Collectors.toMap(Project::getId, Project::getName));
        List<InvoiceView> views = invoices.findAll().stream()
                .sorted(Comparator.comparing(Invoice::getId))
                .map(i -> {
                    BigDecimal paid = payments.findByInvoiceIdOrderByIdAsc(i.getId()).stream()
                            .map(Payment::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
                    String status = InvoiceStatus.derive(i.getStatus(), i.getAmount(), paid);
                    return new InvoiceView(i.getId(), i.getProjectId(),
                            nameByProject.get(i.getProjectId()), i.getAmount(), status);
                })
                .collect(Collectors.toList());
        response.send(views);
    }

    /** An invoice plus the name of the project it bills, as the all-invoices list needs it. */
    public static class InvoiceView {
        private final Long id;
        private final Long projectId;
        private final String projectName;
        private final BigDecimal amount;
        private final String status;

        public InvoiceView(Long id, Long projectId, String projectName, BigDecimal amount,
                String status) {
            this.id = id;
            this.projectId = projectId;
            this.projectName = projectName;
            this.amount = amount;
            this.status = status;
        }

        public Long getId() {
            return id;
        }

        public Long getProjectId() {
            return projectId;
        }

        public String getProjectName() {
            return projectName;
        }

        public BigDecimal getAmount() {
            return amount;
        }

        public String getStatus() {
            return status;
        }
    }
}

import { formatMoney } from '../../ui/money';
import { InvoiceLineItemRow } from '../../slots/defs/invoiceLineItemRow';
import { useLineItems } from './lineItems';
import { useInvoiceSummary } from './invoiceSummary';

// An invoice's line items and what they add up to. Reads its own query key (scoped to the invoice)
// and derives the invoice amount from the rows — the total is never stored on the client, so it
// always matches the list. Each row shows a description, how many, the price of each, and that
// line's own amount (qty * unit price). The table is always rendered, so an invoice with no lines
// yet still shows the region (and a $0.00 total) ready for the first line to be added.
export function LineItemList({ invoiceId }: { invoiceId: number }) {
  const { data: lineItems } = useLineItems(invoiceId);
  const { data: summary } = useInvoiceSummary(invoiceId);

  if (!lineItems) {
    return null;
  }

  // The lines sum to the subtotal; the invoice's amount is that less any discount, worked out on the
  // server (see the summary panel). Fall back to the subtotal while the summary loads — an invoice
  // with no discount bills its full subtotal.
  const subtotal = lineItems.reduce(
    (sum, line) => sum + Number(line.qty) * Number(line.unitPrice),
    0,
  );
  const total = summary ? Number(summary.total) : subtotal;

  return (
    <table data-testid="invoice-lineitems-table">
      <thead>
        <tr>
          <th>Description</th>
          <th>Qty</th>
          <th>Unit</th>
          <th>Unit price</th>
          <th>Amount</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        {lineItems.map((line) => (
          <tr key={line.id} data-testid={`lineitem-row-${line.id}`}>
            <td data-testid="lineitem-description">{line.description}</td>
            <td data-testid="lineitem-qty">{line.qty}</td>
            <td data-testid="lineitem-unit">{line.unit}</td>
            <td data-testid="lineitem-unitprice">{formatMoney(line.unitPrice)}</td>
            <td data-testid="lineitem-amount">
              {formatMoney(Number(line.qty) * Number(line.unitPrice))}
            </td>
            <td>
              <InvoiceLineItemRow.Slot lineItem={line} />
            </td>
          </tr>
        ))}
      </tbody>
      <tfoot>
        <tr>
          <td>Total</td>
          <td></td>
          <td></td>
          <td></td>
          <td data-testid="invoice-amount">{formatMoney(total)}</td>
          <td></td>
        </tr>
      </tfoot>
    </table>
  );
}

